 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    spans = []
    for r in range(h):
        cols = [c for rr, c in markers if rr == r]
        if len(cols) >= 2:
            spans.append([(r, c) for c in range(min(cols), max(cols) + 1)])
    for c in range(w):
        rows = [r for r, cc in markers if cc == c]
        if len(rows) >= 2:
            spans.append([(r, c) for r in range(min(rows), max(rows) + 1)])
    on_span = {p for span in spans for p in span}
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            component = []
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            if any(p in on_span for p in component):
                for y, x in component:
                    out[y][x] = 1
    for r, c in on_span:
        if grid[r][c] == 0:
            out[r][c] = 1
    return out
